body {
  font-family: system-ui, sans-serif;
  margin: 0;
  background: #f6f7f9;
}

.activity {
  max-width: 960px;
  margin: 3rem auto;
  padding: 2rem;
  background: #fff;
  border-radius: 8px;
}

.activity h1 {
  margin-top: 0;
  font-size: 1.5rem;
}

#activity-table {
  width: 100%;
  border-collapse: collapse;
}

#activity-table th,
#activity-table td {
  text-align: left;
  padding: 0.5rem;
  border-bottom: 1px solid #e3e5e8;
}

